"<svg viewBox=\"0 0 {0} {1}\" width=\"{2}\"><polygon points=\"20,{3} {4},{5} {6},10\" fill=\"#e3f1ff\" stroke=\"#2d2a32\" stroke-width=\"3\"/>\n  <line x1=\"{7}\" y1=\"10\" x2=\"{8}\" y2=\"{9}\" stroke=\"#e8475a\" stroke-width=\"2.5\" stroke-dasharray=\"6 4\"/>\n  <text x=\"{10}\" y=\"{11}\" font-size=\"16\" font-weight=\"700\" fill=\"#e8475a\">h = {12} cm</text>\n  <text x=\"{13}\" y=\"{14}\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#2d2a32\">taban = {15} cm</text></svg>":"<svg viewBox=\"0 0 {0} {1}\" width=\"{2}\"><polygon points=\"20,{3} {4},{5} {6},10\" fill=\"#e3f1ff\" stroke=\"#2d2a32\" stroke-width=\"3\"/>\n  <line x1=\"{7}\" y1=\"10\" x2=\"{8}\" y2=\"{9}\" stroke=\"#e8475a\" stroke-width=\"2.5\" stroke-dasharray=\"6 4\"/>\n  <text x=\"{10}\" y=\"{11}\" font-size=\"16\" font-weight=\"700\" fill=\"#e8475a\">h = {12} cm</text>\n  <text x=\"{13}\" y=\"{14}\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#2d2a32\">base = {15} cm</text></svg>",
